style.css:
[class~="o-tab-btn--infinity"], 
[class~="o-tab-btn--infinity o-tab-btn--active"] {
  background-color: black !important;
  text-shadow:0px 0px 4px var(--color-infinity), 
    0px 0px 8px var(--color-infinity);
}

[class~="o-tab-btn--eternity"], 
[class~="o-tab-btn--eternity o-tab-btn--eternity"] {
  background-color: black !important;
  text-shadow:0px 0px 4px var(--color-eternity), 
    0px 0px 8px var(--color-eternity);
}
